-- Add representative tools in music, voice, coding, and professional video.

insert into public.tools (
  name, description, full_description, url, logo_url,
  pricing_type, pricing_start_at, pricing_summary, pricing_details, pricing_currency, pricing_url, pricing_verified_at,
  korean_support_level, is_verified, is_domestic, has_api, api_url, ai_type, tool_scope,
  primary_features, secondary_features, key_benefits, best_for, limitations,
  verification_sources, verified_at, updated_at
)
select * from (values
  ('Suno','텍스트와 오디오에서 보컬·연주가 포함된 음악을 생성하고 편집하는 AI #음악생성 #보컬 #오디오편집 #작곡','Suno는 설명이나 가사로 완성된 노래를 생성하고 오디오 업로드, 리믹스, 보컬·연주 추가, 스템 분리와 편집을 제공하는 AI 음악 제작 서비스입니다.','https://suno.com/','https://suno.com/favicon.ico','Freemium','$0','무료 일 50크레딧 · Pro 연간 결제 월 $8부터',array['Free는 매일 갱신되는 50크레딧을 제공하지만 상업적 이용은 허용하지 않습니다.','Pro는 연간 결제 기준 월 $8에 월 2,500크레딧과 상업 이용 권리를 제공합니다.','구독 크레딧은 이월되지 않으며 추가 구매 크레딧은 활성 구독이 있어야 사용할 수 있습니다.'],'USD','https://suno.com/pricing',now(),'UI only',true,false,false,null,'Native','specialized',array['AI 음악 생성','보컬·연주 생성','음악 편집'],array['오디오 업로드','스템 분리','사용자 음성'],array['가사나 설명에서 완성된 노래 생성','무료 일일 크레딧으로 체험','유료 플랜에서 신규 곡 상업 이용 지원'],array['노래 초안을 빠르게 만들려는 사용자','보컬과 반주를 함께 생성하려는 음악 창작자','기존 오디오를 리믹스·편집하려는 사용자'],array['무료 플랜 생성곡은 상업적으로 이용할 수 없습니다.','유료 전 생성곡에 상업 이용 권리가 소급 적용되지 않습니다.','업로드 음성과 음악에 필요한 권리를 확보해야 합니다.','공식 공개 API는 확인되지 않았습니다.'],array['https://suno.com/','https://suno.com/pricing'],now(),now()),
  ('ElevenLabs','자연스러운 다국어 음성·더빙·효과음과 대화형 음성 에이전트를 만드는 AI #음성생성 #더빙 #효과음 #음성에이전트','ElevenLabs는 텍스트 음성 변환, 음성 복제와 변환, 다국어 더빙, 효과음·음악 및 실시간 대화형 음성 에이전트를 제공하는 AI 오디오 플랫폼입니다. 웹 서비스와 공식 API를 함께 운영합니다.','https://elevenlabs.io/','https://elevenlabs.io/favicon.ico','Freemium','$0','무료 플랜 · Starter 월 $6부터 · API 사용 가능',array['Free 플랜에서 제한된 문자와 생성 기능을 체험할 수 있습니다.','Starter는 월 $6부터이며 플랜에 따라 문자·음성·에이전트 사용량이 확대됩니다.','대부분의 API 엔드포인트는 무료 플랜에서도 사용 가능하고 사용량은 플랜 한도에서 차감됩니다.'],'USD','https://elevenlabs.io/pricing',now(),'Full Support',true,false,true,'https://elevenlabs.io/docs/api-reference','Native','specialized',array['텍스트 음성 변환','음성 복제·변환','다국어 더빙'],array['효과음·음악','음성 에이전트','API 연동'],array['자연스러운 다국어 음성 생성','더빙·효과음·대화형 에이전트 통합','웹 기능을 연동하는 공식 API'],array['영상 내레이션과 더빙을 만드는 사용자','브랜드·캐릭터 음성을 제작하는 팀','음성 AI를 제품에 연동하려는 개발자'],array['음성 복제에는 본인 또는 권리자의 명확한 동의가 필요합니다.','플랜별 상업 이용·음성 복제 범위가 다릅니다.','긴 음성과 고품질 모델은 더 많은 사용량을 소비합니다.'],array['https://elevenlabs.io/pricing','https://elevenlabs.io/pricing/api','https://elevenlabs.io/docs/api-reference'],now(),now()),
  ('Cursor','코드베이스를 이해하고 편집·실행하는 AI 에이전트가 통합된 코드 편집기 #코딩 #AI에이전트 #코드편집 #개발','Cursor는 코드 완성, 코드베이스 질의응답, 다중 파일 편집, 터미널 실행, 클라우드 에이전트와 코드 리뷰를 제공하는 AI 중심 코드 편집기입니다. 무료 Hobby와 개인·팀 유료 플랜을 운영합니다.','https://cursor.com/','https://cursor.com/favicon.ico','Freemium','$0','Hobby 무료 · Pro 월 $20부터',array['Hobby는 신용카드 없이 제한된 Agent 요청과 Composer를 제공합니다.','Pro는 월 $20에 확장된 Agent 한도, 고급 모델, MCP·skills·hooks와 클라우드 에이전트를 제공합니다.','포함 사용량을 넘으면 설정에 따라 추가 사용량 과금이 발생할 수 있습니다.'],'USD','https://cursor.com/pricing',now(),'None',true,false,false,null,'Native','specialized',array['AI 코드 편집','코딩 에이전트','코드베이스 검색'],array['클라우드 에이전트','코드 리뷰','MCP·자동화'],array['프로젝트 문맥을 반영한 다중 파일 수정','편집기·터미널·에이전트 통합','Privacy Mode를 통한 학습 제외 지원'],array['AI와 함께 코드를 작성·수정하는 개발자','큰 코드베이스를 탐색하는 팀','반복 개발 작업을 에이전트에 맡기려는 사용자'],array['에이전트가 만든 변경은 테스트와 보안 검토가 필요합니다.','모델 선택과 작업량에 따라 포함 사용량 소진 속도가 다릅니다.','민감한 코드에는 Privacy Mode와 조직 정책을 확인해야 합니다.','독립적인 일반 모델 API는 제공하지 않습니다.'],array['https://cursor.com/pricing','https://docs.cursor.com/account/pricing','https://cursor.com/terms/pricing'],now(),now()),
  ('GitHub Copilot','IDE·터미널·GitHub에서 코드 완성·채팅·리뷰·코딩 에이전트를 제공하는 AI #코딩 #코드완성 #AI에이전트 #코드리뷰','GitHub Copilot은 코드 완성과 채팅, Agent Mode, CLI, 코드 리뷰, 클라우드 코딩 에이전트를 GitHub와 여러 IDE에 통합한 AI 개발 도구입니다. 제한적 무료 플랜과 개인·조직용 유료 플랜을 제공합니다.','https://github.com/features/copilot','https://github.com/favicon.ico','Freemium','$0','Free 월 2,000회 완성 · Pro 월 $10부터',array['Free는 월 2,000회 코드 완성과 제한된 채팅·에이전트 사용량을 제공합니다.','Pro는 월 $10에 무제한 코드 완성, 코드 리뷰와 클라우드 에이전트를 제공합니다.','AI Credits를 초과한 추가 사용은 사용자가 예산을 허용한 경우 별도 과금될 수 있습니다.'],'USD','https://github.com/features/copilot/plans',now(),'UI only',true,false,false,null,'Augmented','specialized',array['코드 완성·채팅','Agent Mode','코드 리뷰'],array['Copilot CLI','클라우드 에이전트','다중 모델 선택'],array['GitHub와 주요 IDE에 통합된 개발 경험','무료 플랜으로 코드 완성과 에이전트 체험','개인부터 기업까지 관리·정책 기능 제공'],array['IDE에서 실시간 코딩 지원을 원하는 개발자','이슈·리뷰·CLI까지 AI를 연결하려는 사용자','조직 단위 AI 개발 정책이 필요한 팀'],array['생성 코드의 정확성·보안·라이선스를 직접 검토해야 합니다.','Free와 개인 플랜 데이터는 설정에 따라 모델 개선에 사용될 수 있어 옵트아웃을 확인해야 합니다.','추가 AI Credits 과금에는 별도 예산 설정이 필요합니다.','일반 모델 호출용 API 상품이 아니라 개발 도구입니다.'],array['https://github.com/features/copilot','https://github.com/features/copilot/plans','https://docs.github.com/en/billing/concepts/product-billing/github-copilot-billing'],now(),now()),
  ('Runway','전문적인 AI 영상·이미지·오디오 생성과 편집 워크플로를 제공하는 스튜디오 #AI영상 #영상편집 #이미지생성 #크리에이티브','Runway는 텍스트·이미지 기반 영상과 이미지 생성, 영상 변환·편집, 오디오와 캐릭터 기능을 제공하는 전문 AI 미디어 제작 플랫폼입니다. 무료 체험 크레딧, 유료 구독과 별도 공식 API를 운영합니다.','https://runwayml.com/','https://runwayml.com/favicon.ico','Freemium','$0','무료 일회성 125크레딧 · 유료 플랜 및 API 별도',array['Free는 갱신되지 않는 일회성 125크레딧과 일부 모델을 제공합니다.','무료 생성 영상에는 워터마크가 포함되고 유료 플랜에서 모델·크레딧·내보내기가 확대됩니다.','웹 앱 크레딧과 API 크레딧은 서로 별도입니다.'],'USD','https://runwayml.com/pricing',now(),'None',true,false,true,'https://docs.dev.runwayml.com/','Native','specialized',array['AI 영상 생성·편집','이미지 생성','영상 변환'],array['오디오 생성','캐릭터','API·워크플로'],array['영상 제작을 위한 생성·편집 기능 통합','다양한 전문 영상 모델과 제어 기능','영상·이미지·오디오 공식 API 제공'],array['광고·영화·콘셉트 영상을 제작하는 사용자','생성 영상과 후반 편집을 함께 수행하는 팀','미디어 생성을 제품에 연동하려는 개발자'],array['무료 크레딧은 한 번만 지급되며 영상에 워터마크가 적용됩니다.','영상 길이와 모델에 따라 크레딧이 빠르게 소모될 수 있습니다.','웹 구독과 API 크레딧은 공유되지 않습니다.','생성물에 사용한 인물·브랜드·참조 자료의 권리를 확인해야 합니다.'],array['https://help.runwayml.com/hc/en-us/articles/50404627334547-Free-plan-details','https://help.runwayml.com/hc/en-us/articles/15124877443219-How-do-credits-work','https://docs.dev.runwayml.com/guides/pricing/'],now(),now())
) as seed(name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,korean_support_level,is_verified,is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at)
where not exists (select 1 from public.tools where lower(tools.url)=lower(seed.url));

with assignments(tool_url,category_slug) as (values
 ('https://suno.com/','video-audio'),
 ('https://elevenlabs.io/','video-audio'), ('https://elevenlabs.io/','development'),
 ('https://cursor.com/','development'), ('https://cursor.com/','productivity'),
 ('https://github.com/features/copilot','development'), ('https://github.com/features/copilot','productivity'),
 ('https://runwayml.com/','video-audio'), ('https://runwayml.com/','design-art')
)
insert into public.tool_categories(tool_id,category_id)
select tools.id,categories.id from assignments
join public.tools on lower(tools.url)=lower(assignments.tool_url)
join public.categories on lower(categories.slug)=lower(assignments.category_slug)
on conflict (tool_id,category_id) do nothing;
